import sys, json, time, random, os
import numpy as np

def main():
    start_time = time.time()
    if len(sys.argv) < 3:
        return
    instance_path = sys.argv[1]
    budget = float(sys.argv[2])
    if 'QAP_TIME_LIMIT_S' in os.environ:
        budget = min(budget, float(os.environ['QAP_TIME_LIMIT_S']))
    with open(instance_path) as f:
        data = json.load(f)
    n = data['n']
    A = np.array(data['A'], dtype=int)
    B = np.array(data['B'], dtype=int)
    best_cost = None
    best_perm = None
    start_time = time.time()
    while time.time() - start_time < budget:
        perm = list(range(n))
        random.shuffle(perm)
        cost = 0
        for i in range(n):
            for j in range(n):
                cost += A[i, j] * B[perm[i], perm[j]]
        if best_cost is None or cost < best_cost:
            best_cost = cost
            best_perm = perm[:]
        improved = True
        while improved:
            improved = False
            for _ in range(100):
                if time.time() - start_time >= budget:
                    break
                i, j = random.sample(range(n), 2)
                perm[i], perm[j] = perm[j], perm[i]
                new_cost = 0
                for k in range(n):
                    for l in range(n):
                        new_cost += A[k, l] * B[perm[k], perm[l]]
                if new_cost < cost:
                    cost = new_cost
                    improved = True
                else:
                    perm[i], perm[j] = perm[j], perm[i]
        if time.time() - start_time >= budget:
            break
    out_perm = [x + 1 for x in best_perm]
    print("PERMUTATION: " + " ".join(map(str, out_perm)), flush=True)

if __name__ == "__main__":
    main()
